"""Produce a descriptive report; never select/retrain models from results."""
import collections,hashlib,json,pathlib,statistics
import numpy as np
ROOT=pathlib.Path(__file__).resolve().parent

def main():
    o=json.loads((ROOT/'results_v1_1/metrics.json').read_text());checks=json.loads((ROOT/'results_v1_1/independent_checks.json').read_text());native=json.loads((ROOT/'native_checks.json').read_text());manifest=json.loads((ROOT/'manifest.json').read_text());integrity=json.loads((ROOT/'integrity.json').read_text());external=json.loads((ROOT/'results_v1_1/external_summary_corrected.json').read_text());runs=o['runs'];arms=['paired','shuffled_pairing','no_graph','text_only','shuffled_edges'];stats={}
    # Primary questions are eight held-out generated parents; counter is separately reported.
    for arm in arms:
        rows=[r for r in runs if r['arm']==arm];stats[arm]={'synthetic_r1':float(np.mean([r['metrics']['per_sample_r1'][:-1] for r in rows])),'synthetic_r5':float(np.mean([r['metrics']['per_sample_r5'][:-1] for r in rows])),'seed_r1':[float(np.mean(r['metrics']['per_sample_r1'][:-1])) for r in rows],'seed_r5':[float(np.mean(r['metrics']['per_sample_r5'][:-1])) for r in rows],'wall_seconds':sum(r['wall_seconds'] for r in rows),'allocated_parameters':rows[0]['parameter_count'],'gradient_parameters':sorted({r['last_step_gradient_parameters'] for r in rows}),'downstream':{name:np.mean([np.mean(r['metrics']['downstream'][name]['per_sample_log1p_abs_error'][:-1],axis=0) for r in rows],axis=0).tolist() for name in ['counts_only','embedding_plus_counts','retrieval_augmented']}}
    rng=np.random.default_rng(20261028);contrasts={}
    for control in arms[1:]:
        diffs=[]
        for f in range(16,24):
            deltas=[]
            for seed in [11,23,37]:
                a=next(r for r in runs if r['seed']==seed and r['arm']=='paired')['metrics'];b=next(r for r in runs if r['seed']==seed and r['arm']==control)['metrics'];indices=[j for j,sid in enumerate(a['test_sample_ids']) if int(sid[1:3])==f];deltas.append(np.mean(np.array(a['per_sample_r1'])[indices]-np.array(b['per_sample_r1'])[indices]))
            diffs.append(float(np.mean(deltas)))
        boot=np.array(diffs)[rng.integers(0,8,(2000,8))].mean(1);contrasts[control]={'r1_delta':float(np.mean(diffs)),'parent_bootstrap_95':np.quantile(boot,[.025,.975]).tolist(),'parents':8}
    summary={'label':'CircuitFusion real-synthesis CPU methodology closure; not original PPA reproduction','status':'feasible_methodology_loop_completed_with_substitutions','training_runs':len(runs),'steps_per_run':400,'total_corrected_optimizer_steps':len(runs)*400,'corpus':{'train_cones':95,'test_generated_cones':48,'test_generated_parents':8,'external_open_counter_cones':1,'native_input_assignments':native['assignments'],'formal_proofs':integrity['formal_proofs']},'primary_results':stats,'paired_contrasts':contrasts,'external_summary_corrected':external['rows'],'independent_metric_checks_passed':checks['all_passed'],'resources':o['resources'],'protocol_sha256':o['protocol_sha256'],'interpretation':'No consistent held-out graph or correct-pairing advantage established at this budget. Prior AST-summary synthetic success does not transfer to this stronger setup; multiple simultaneous changes prevent attributing the drop solely to summaries.','remaining_gaps':['summary substitute is coarse behavioral heuristic, not LLM','small GRU/GNN port differs from frozen 7B/BERT/Graphormer architecture','only one small open external design; rest are semantics-checked generated parents','no industrial synthesis constraints or original PPA labels','no original data/checkpoint/full-result reproduction'],'next_gate':'method loop closed; next useful research is a predeclared Graphormer/stronger-code-encoder comparison and broader licensed real RTL, rather than expanding training to chase these metrics','no_extra_resources_required_for_completed_loop':True,'paid_or_external_LLM_used':False,'push_performed':False}
    (ROOT/'SUMMARY.json').write_text(json.dumps(summary,indent=2)+'\n')
    lines=['# CircuitFusion methodology closure — CPU, real synthesis','', '**Outcome: the feasible end-to-end loop is closed, with a negative controlled result.** Correct pairing and the graph path do not show a consistent held-out advantage over trained graph removal, text-only or corrupted-edge controls at the frozen budget. This is evidence about this small port, not a finding that the paper is invalid. No extra resource is required for the completed loop.', '', '## What actually ran','', '144 accepted designs: 95 training cones from 16 generated parent families, 48 test cones from 8 different generated families, and one unchanged open Yosys counter held out separately. One duplicate candidate was excluded before training. Family variants never cross splits; commutative canonical expression skeletons and complete truth tables do not overlap across splits. All code streams are complete (at most 75 tokens), not artificially truncated. The training set covers test graph types; three unknown HDL tokens occur only in the external 3-bit counter.', '', 'Each sequential Verilog design goes through actual Yosys `proc`, explicit DFF D/Q boundary extraction, equivalent RTL optimization, `techmap`, ABC Boolean mapping, independent gate evaluation, formal equivalence, multimodal training, held-out retrieval, and train-pool-only retrieval-augmented structural-proxy regression. All 144 formal proofs have per-design evidence. Native GCC evaluation agrees byte-for-byte on 2,342,944 input cases; the Python reference/operator/gate checks cover 7,028,832 input/view comparisons. Corrected graph tensors distinguish all 144 functions. Arbitrary node-order changes preserve model outputs; graph-removed outputs are independent of graph inputs.', '', 'The learned port includes full HDL GRU states, directed graph message passing with operand/output bit positions, summary-query cross-attention, equivalent-view contrastive learning, graph/summary multi-positive contrastive learning, masked node/token reconstruction, summary matching, a learned gate encoder and RTL–gate alignment. All weights start randomly. It is a scaled mechanism port, not execution of the original foundation models. Gate count/depth targets are generated structural measurements, never relabeled as physical PPA.', '', '## Removing summary-template leakage','', 'The old AST-verbalization summaries are not used. New descriptions use only coarse input/output properties, state dependence and bit activity: four classes across 144 samples (largest class 109). They include no AST, operation names, constants, circuit IDs, paths, gate counts or depths. Identical summaries are treated as multi-positive and are not deliberately mislabeled as mismatches. These descriptions are explicitly **heuristics, not LLM-generated natural-language summaries**. Their loss of semantic detail is a real fidelity limit.', '', 'The counter has no data operands. A later correctness audit found its generic operand-exchange sentence inapplicable. That sentence was removed in a separately logged checkpoint-only evaluation; training and the primary 48-cone results are unchanged. Raw original evaluation remains preserved, and corrected external results are reported separately.', '', '## Matched-budget results','', 'Each corrected arm used the same three seeds (11,23,37), 400 minibatches, batch size 16, width 32, optimizer, learning rate and shared sample schedule: 6,000 updates in 15 runs. Controls were fixed before corrected training. Shared allocated modules match parameter counts; graph removal and text-only have fewer active gradient parameters and lower FLOPs, which are reported. Shuffled edges retains the full graph modules/losses. No best-seed selection or outcome-driven hyperparameter tuning.', '', 'Primary queries: 48 cones in eight held-out generated parents, ranked against 49 held-out gate candidates. Chance Recall@1 = 2.04%, Recall@5 = 10.20%.', '', '| Arm | Recall@1 | Recall@5 | Recall@1 seeds 11 / 23 / 37 | Active gradient parameters |','|---|---:|---:|---|---|']
    for arm in arms:
        s=stats[arm];lines.append(f"| {arm} | {s['synthetic_r1']:.2%} | {s['synthetic_r5']:.2%} | {' / '.join(f'{v:.2%}' for v in s['seed_r1'])} | {s['gradient_parameters']} |")
    lines+=['', '| Paired minus control, Recall@1 | Mean difference | Exploratory 95% parent bootstrap |','|---|---:|---|']
    for arm,c in contrasts.items():lines.append(f"| {arm} | {100*c['r1_delta']:+.2f} pp | [{100*c['parent_bootstrap_95'][0]:+.2f}, {100*c['parent_bootstrap_95'][1]:+.2f}] pp |")
    lines+=['', 'Intervals resample eight parent families, averaging predeclared seeds, rather than treating cones as independent. This small synthetic-family universe is not population-level evidence. The counter has one cone and cannot substantiate broad real-RTL generalization.', '', '| Corrected external counter | Recall@1 by seed | Recall@5 by seed |','|---|---|---|']
    for arm in arms:
        er=[r for r in external['rows'] if r['arm']==arm];lines.append(f"| {arm} | {[r['recall_at_1'] for r in er]} | {[r['recall_at_5'] for r in er]} |")
    lines+=['', '## Downstream closure: structural proxies, not PPA','', 'Known-circuit retrieval uses only training-family RTL embeddings and measured gate count/depth. Training queries exclude the entire own parent family; held-out queries use training parents only. All predictors share available RTL operator counts. Targets are log1p transformed; a fixed alpha=1 ridge model is fitted using training data only. Counts-only is a new cheap baseline; text-only embeddings plus counts also receive counts, which are reported transparently.', '', '| Arm | Embedding + counts MAE (log1p gate count / depth) | Retrieval-augmented MAE |','|---|---|---|']
    for arm,s in stats.items():lines.append(f"| {arm} | {' / '.join(f'{v:.4f}' for v in s['downstream']['embedding_plus_counts'])} | {' / '.join(f'{v:.4f}' for v in s['downstream']['retrieval_augmented'])} |")
    baseline=stats['paired']['downstream']['counts_only'];lines+=['',f"Shared counts-only MAE: {baseline[0]:.4f} / {baseline[1]:.4f}. No target or count from a test netlist enters any downstream prediction. The supplied test gate netlists are used only as retrieval candidates in the separate cross-stage retrieval evaluation and as ground truth for scoring.",'', '## Failures, repairs and limits','', '- Protocol 1.0 was stopped after three completed seed11 runs when independent checks proved 144 semantic functions collapsed to 81 graph tensors because aggregated word edges erased bit positions. The entire attempt, data, code, checkpoint and logs are preserved in `attempt1/`. Protocol 1.1 added explicit operand pins/output bits and actual alternate HDL augmentation before corrected training. Hyperparameters/seeds/steps were unchanged. Early incomplete results are not pooled with the corrected comparison.', '- Initial YoWASP startup failed because its default cache location was read-only. A documented per-process writable task cache fixed it; no permissions or security settings changed. No GitHub API denial was bypassed. Two absent guessed ALU files were recorded as path-specific 404s; a third-party-borrowed source was excluded.', '- The native and metric verifiers are independently written checks, not independent neural-network implementations. Checkpoint verification uses NumPy rank calculations and reconstructs train-only/family-excluded retrieval and ridge errors. All corrected runs must pass before this report is generated.', '- Graph rewiring is deterministic for seed and batch position, preserves node and edge counts, and may produce cycles. It is a corrupted-input control, not a semantics-preserving circuit. Active losses/compute differ in removed-modality arms. The graph path is a three-layer directed message-passing substitute for the paper Graphormer, and the small GRUs replace pretrained 7B/BERT encoders.', '- The earlier 66.7% synthetic retrieval result does not survive the stronger setup. Dataset, summaries, synthesis, representation and objectives changed together; this is not a causal estimate of summary leakage alone. The observed null should not be advertised as evidence against the paper.', '', '## Resources, evidence and remaining gate','', f"Corrected training/evaluation wall time: {o['resources']['wall_seconds']:.2f} seconds; peak training-process RSS: {o['resources']['peak_rss_kib']/1024:.1f} MiB; PyTorch {o['resources']['torch']}, two Torch CPU threads. The interrupted run and setup are additional costs and remain logged. Corrected preparation took {integrity['wall_seconds']:.2f} seconds; native checking {native['wall_seconds']:.2f} seconds. Tool compilation peak was not separately captured. New wheel payload about 26.8 MB; no weights/API/data-service downloads or costs. Compiled WASM cache is about 210 MiB and is excluded from Git.", '', 'The original code/audit, previous method port and this corrected real-synthesis port remain separate. Read `MECHANISM_COVERAGE.md`, `EXECUTION.md`, both protocols and `results_v1_1/metrics.json` for provenance and deviations. The official Yosys counter and ISC COPYING are stored with URL hashes. This tranche used no paid services, credentials, security changes, gated agreements, LLM calls, publication, push or PR.', '', '**Remaining gap:** graph contribution and family-general semantic alignment remain unproven at this budget. A future predeclared comparison with a closer Graphormer/code encoder and broader licensed real RTL would test representation capacity and transfer. Original GPT summaries, 7B encoder/checkpoints, commercial constraints and PPA labels remain unavailable or outside this tranche. Full paper reproduction remains L3. The currently feasible controlled methodology loop is complete; no further scaling is launched.']
    (ROOT/'REPORT.md').write_text('\n'.join(lines)+'\n');print(json.dumps({'results':stats,'contrasts':contrasts,'resources':o['resources']},indent=2))
if __name__=='__main__':main()
